<?php
require_once __DIR__ . '/includes/bootstrap.php';
riderRequireLogin(); ensureMisTables();
$conn=dbConnect(); $riderId=(int)$_SESSION['rider_id']; $notice=$_SESSION['rider_notice']??''; unset($_SESSION['rider_notice']);
function riderAssignment($conn,$id,$riderId){$s=mysqli_prepare($conn,'SELECT a.*,o.email,o.name customer_name,o.phone,o.address,p.payment_method,f.total_amount FROM order_delivery_assignments a JOIN orders o ON o.orderid=a.orderid LEFT JOIN order_payments p ON p.orderid=o.orderid LEFT JOIN order_financials f ON f.orderid=o.orderid WHERE a.assignment_id=? AND a.rider_id=? AND a.is_current=1 FOR UPDATE');mysqli_stmt_bind_param($s,'ii',$id,$riderId);mysqli_stmt_execute($s);return mysqli_fetch_assoc(mysqli_stmt_get_result($s));}
if($_SERVER['REQUEST_METHOD']==='POST'&&hash_equals(riderToken(),$_POST['csrf']??'')){
 $id=(int)($_POST['assignment_id']??0);$action=$_POST['action']??'';if(!$id||!mysqli_begin_transaction($conn))riderRedirect('home.php','Could not update this delivery.');$a=riderAssignment($conn,$id,$riderId);$ok=(bool)$a;$message='';
 if($ok&&$action==='accept'&&$a['status']==='assigned'){$s=mysqli_prepare($conn,"UPDATE order_delivery_assignments SET status='accepted',accepted_at=NOW() WHERE assignment_id=?");mysqli_stmt_bind_param($s,'i',$id);$ok=mysqli_stmt_execute($s);$message='Delivery accepted.';}
 elseif($ok&&$action==='pickup'&&$a['status']==='accepted'){$s=mysqli_prepare($conn,"UPDATE order_delivery_assignments SET status='picked_up' WHERE assignment_id=?");mysqli_stmt_bind_param($s,'i',$id);$ok=mysqli_stmt_execute($s);$message='Pickup recorded.';}
 elseif($ok&&$action==='out_for_delivery'&&$a['status']==='picked_up'){ $otp=(string)random_int(100000,999999);$hash=password_hash($otp,PASSWORD_DEFAULT);$expiry=date('Y-m-d H:i:s',time()+900);$s=mysqli_prepare($conn,"UPDATE order_delivery_assignments SET status='out_for_delivery' WHERE assignment_id=?");mysqli_stmt_bind_param($s,'i',$id);$ok=mysqli_stmt_execute($s);$s=mysqli_prepare($conn,'INSERT INTO delivery_otps(orderid,otp_hash,expires_at,attempts,verified_at) VALUES(?,?,?,0,NULL) ON DUPLICATE KEY UPDATE otp_hash=VALUES(otp_hash),expires_at=VALUES(expires_at),attempts=0,verified_at=NULL');mysqli_stmt_bind_param($s,'iss',$a['orderid'],$hash,$expiry);$ok=$ok&&mysqli_stmt_execute($s);if($ok)createNotification('customer',$a['email'],'Delivery OTP','Your delivery OTP for order #'.$a['orderid'].' is '.$otp.'. It expires in 15 minutes. Share it only with the rider at your door.','track-order.php?order='.$a['orderid']);$message='Customer OTP generated. Ask the customer to open Foodera notifications.';}
 elseif($ok&&$action==='deliver'&&$a['status']==='out_for_delivery'){ $otp=trim($_POST['otp']??'');$s=mysqli_prepare($conn,'SELECT * FROM delivery_otps WHERE orderid=? FOR UPDATE');mysqli_stmt_bind_param($s,'i',$a['orderid']);mysqli_stmt_execute($s);$record=mysqli_fetch_assoc(mysqli_stmt_get_result($s));$valid=$record&&empty($record['verified_at'])&&$record['attempts']<5&&strtotime($record['expires_at'])>=time()&&password_verify($otp,$record['otp_hash']);if(!$valid){if($record){$u=mysqli_prepare($conn,'UPDATE delivery_otps SET attempts=attempts+1 WHERE otp_id=?');mysqli_stmt_bind_param($u,'i',$record['otp_id']);mysqli_stmt_execute($u);}$ok=false;$message='Invalid or expired OTP.';}else{$u=mysqli_prepare($conn,'UPDATE delivery_otps SET verified_at=NOW() WHERE otp_id=?');mysqli_stmt_bind_param($u,'i',$record['otp_id']);$ok=mysqli_stmt_execute($u);$s=mysqli_prepare($conn,"UPDATE order_delivery_assignments SET status='delivered',delivered_at=NOW() WHERE assignment_id=?");mysqli_stmt_bind_param($s,'i',$id);$ok=$ok&&mysqli_stmt_execute($s);if(($a['payment_method']??'')==='cod'){$c=mysqli_prepare($conn,"INSERT INTO cod_collections(orderid,rider_id,expected_amount,status) VALUES(?,?,?,'pending') ON DUPLICATE KEY UPDATE rider_id=VALUES(rider_id),expected_amount=VALUES(expected_amount)");mysqli_stmt_bind_param($c,'iid',$a['orderid'],$riderId,$a['total_amount']);$ok=$ok&&mysqli_stmt_execute($c);}$u=mysqli_prepare($conn,"UPDATE delivery_riders SET availability='available' WHERE rider_id=?");mysqli_stmt_bind_param($u,'i',$riderId);$ok=$ok&&mysqli_stmt_execute($u);$message='Delivery verified successfully.';}}
 elseif($ok&&$action==='failed'&&trim($_POST['reason']??'')!==''){$reason=trim($_POST['reason']);$s=mysqli_prepare($conn,"UPDATE order_delivery_assignments SET status='failed',failure_reason=? WHERE assignment_id=?");mysqli_stmt_bind_param($s,'si',$reason,$id);$ok=mysqli_stmt_execute($s);$u=mysqli_prepare($conn,"UPDATE delivery_riders SET availability='available' WHERE rider_id=?");mysqli_stmt_bind_param($u,'i',$riderId);$ok=$ok&&mysqli_stmt_execute($u);$message='Delivery issue sent to Foodera admin.';}else{$ok=false;$message='This delivery action is not available.';}
 $ok?mysqli_commit($conn):mysqli_rollback($conn);if($ok&&$action==='deliver'&&($a['payment_method']??'')==='cod'){$cash=mysqli_prepare($conn,"UPDATE cod_collections SET collected_amount=expected_amount,status='recorded',recorded_at=NOW() WHERE orderid=? AND rider_id=?");mysqli_stmt_bind_param($cash,'ii',$a['orderid'],$riderId);mysqli_stmt_execute($cash);$message='Delivery verified and COD collection recorded.';}if($ok){$next=['pickup'=>'picked_up','out_for_delivery'=>'out_for_delivery','deliver'=>'delivered','failed'=>'delivery_failed'][$action]??null;if($next){$transition=orderTransition($a['orderid'],$next,'rider',(string)$riderId,$message);if(!$transition[0])$message=$transition[1];}orderAudit($conn,$a['orderid'],'rider',(string)$riderId,'delivery_'.$action,null,null,$message);}riderRedirect('home.php',$message);
}
$s=mysqli_prepare($conn,"SELECT a.*,o.email,o.name customer_name,o.phone,o.address,p.payment_method,f.total_amount FROM order_delivery_assignments a JOIN orders o ON o.orderid=a.orderid LEFT JOIN order_payments p ON p.orderid=o.orderid LEFT JOIN order_financials f ON f.orderid=o.orderid WHERE a.rider_id=? AND a.is_current=1 AND a.status NOT IN ('delivered','failed','reassigned') ORDER BY FIELD(a.status,'out_for_delivery','picked_up','accepted','assigned'),a.assigned_at");mysqli_stmt_bind_param($s,'i',$riderId);mysqli_stmt_execute($s);$assignments=mysqli_fetch_all(mysqli_stmt_get_result($s),MYSQLI_ASSOC);
foreach($assignments as $a){if($a['status']!=='out_for_delivery')continue;$s=mysqli_prepare($conn,'SELECT otp_id FROM delivery_otps WHERE orderid=? AND verified_at IS NULL AND expires_at>=NOW() LIMIT 1');mysqli_stmt_bind_param($s,'i',$a['orderid']);mysqli_stmt_execute($s);if(mysqli_fetch_assoc(mysqli_stmt_get_result($s)))continue;$otp=(string)random_int(100000,999999);$hash=password_hash($otp,PASSWORD_DEFAULT);$expiry=date('Y-m-d H:i:s',time()+900);$s=mysqli_prepare($conn,'INSERT INTO delivery_otps(orderid,otp_hash,expires_at,attempts,verified_at) VALUES(?,?,?,0,NULL) ON DUPLICATE KEY UPDATE otp_hash=VALUES(otp_hash),expires_at=VALUES(expires_at),attempts=0,verified_at=NULL');mysqli_stmt_bind_param($s,'iss',$a['orderid'],$hash,$expiry);if(mysqli_stmt_execute($s))createNotification('customer',$a['email'],'Delivery OTP','Your delivery OTP for order #'.$a['orderid'].' is '.$otp.'. It expires in 15 minutes. Share it only with the rider at your door.','track-order.php?order='.$a['orderid']);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#ff4b1f"><title>Active deliveries | Foodera</title><link rel="icon" href="../assets/branding/foodera-icon.png"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="rider.css"><link rel="stylesheet" href="dashboard.css"></head><body><main class="rider-shell"><header class="rider-top"><div><div class="rider-brand"><img src="../assets/branding/foodera-wordmark.png" alt="Foodera"></div><p class="rider-kicker">Foodera delivery</p><h1>Hi, <?php echo riderEscape($_SESSION['rider_name']); ?></h1></div><div class="rider-top-actions"><a class="rider-history-link" href="dashboard.php"><i class="bi bi-speedometer2"></i> Dashboard</a><a class="rider-history-link" href="history.php"><i class="bi bi-clock-history"></i> Delivery history</a><a href="logout.php">Sign out <i class="bi bi-box-arrow-right"></i></a></div></header><?php if($notice){?><p class="rider-alert"><?php echo riderEscape($notice);?></p><?php }?><section class="rider-intro"><div><h2>Your delivery list</h2><p>Only orders assigned to you appear here. Keep customer details and delivery OTPs private.</p></div><strong><i class="bi bi-bag-check"></i> <?php echo count($assignments);?> active</strong></section><?php if(!$assignments){?><section class="rider-card rider-empty"><i class="bi bi-bicycle"></i><h2>No active deliveries</h2><p>New tasks will appear here after an admin assigns an order to you.</p><p><a class="rider-history-link" href="history.php">View delivery history <i class="bi bi-arrow-right"></i></a></p></section><?php }else{?><section class="rider-list"><?php foreach($assignments as $a){?><article class="rider-card rider-delivery"><header><div><p class="rider-kicker">Order #<?php echo (int)$a['orderid'];?></p><h2><?php echo riderEscape($a['customer_name']);?></h2></div><span class="rider-status"><?php echo riderEscape(ucwords(str_replace('_',' ',$a['status'])));?></span></header><div class="rider-meta"><span><i class="bi bi-geo-alt"></i><b>Delivery address</b><?php echo riderEscape($a['address']);?></span><span><i class="bi bi-telephone"></i><b>Customer phone</b><a href="tel:<?php echo riderEscape($a['phone']);?>"><?php echo riderEscape($a['phone']);?></a></span><span><i class="bi bi-cash-stack"></i><b>Payment</b><?php echo riderEscape(strtoupper($a['payment_method']??''));?> &middot; Rs <?php echo number_format((float)$a['total_amount']);?></span></div><div class="rider-actions"><form method="post"><input type="hidden" name="csrf" value="<?php echo riderEscape(riderToken());?>"><input type="hidden" name="assignment_id" value="<?php echo (int)$a['assignment_id'];?>"><?php if($a['status']==='assigned'){?><button class="rider-action" name="action" value="accept">Accept task</button><?php }elseif($a['status']==='accepted'){?><button class="rider-action" name="action" value="pickup">Confirm pickup</button><?php }elseif($a['status']==='picked_up'){?><button class="rider-action" name="action" value="out_for_delivery">Start delivery</button><?php }elseif($a['status']==='out_for_delivery'){?><input name="otp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="Customer OTP" required><button class="rider-action" name="action" value="deliver">Verify &amp; deliver</button><?php }?></form><form method="post"><input type="hidden" name="csrf" value="<?php echo riderEscape(riderToken());?>"><input type="hidden" name="assignment_id" value="<?php echo (int)$a['assignment_id'];?>"><input name="reason" maxlength="500" placeholder="Report an issue" required><button class="rider-action rider-danger" name="action" value="failed">Report issue</button></form></div></article><?php }?></section><?php }?></main></body></html>
